function r3WeakInferenceSignalActor(text) {
  const value = String(text || "").trim();
  // Explicit first-person behavior belongs to the current user. Explicit
  // second-person behavior belongs to the active Persona. Otherwise social
  // signals such as「已讀沒回」「回哈哈就轉話題」remain external/scene.
  if (/(?:^|[，,。！？!?\s])我[^。！？!?]{0,48}(?:回|已讀|已读|沒回|没回|不回|轉話題|转话题|不理|忽略)/u.test(value)) return "CURRENT_USER";
  if (/(?:^|[，,。！？!?\s])(?:你|妳)[^。！？!?]{0,48}(?:回|已讀|已读|沒回|没回|不回|轉話題|转话题|不理|忽略)/u.test(value)) return "ACTIVE_CHARACTER_IDENTITY";
  return "EXTERNAL_OTHER";
}

function r3WeakInferenceProposition(text, utteranceAct = null) {
  const target = String(utteranceAct?.target || "").trim();
  const signalActor = r3WeakInferenceSignalActor(text);
  return {
    propositionId: "P_WEAK_INFERENCE",
    type: "WEAK_INFERENCE",
    subject: target && target !== "INFERENCE_TARGET" ? target : "CURRENT_TURN_INFERENCE_TARGET",
    predicate: "INFERENCE_FROM_LIMITED_SIGNAL",
    value: "UNVERIFIED",
    source: "CURRENT_USER_INFERENCE",
    timeScope: "THIS_TURN",
    evidenceClass: "WEAK_INFERENCE",
    signalActor,
    assertionRights: {
      acknowledgeSignal: "ALLOW",
      preserveUncertainty: "REQUIRED",
      confirmInference: "DENY",
      mindReading: "DENY",
      alternateCauseInvention: "DENY",
    },
  };
}

function r3CurrentStateProposition(text, utteranceAct = null) {
  const value = String(text || "");
  if (utteranceAct?.subtype === "CURRENT_OBJECT_QUERY") {
    return {
      propositionId: "P_CURRENT_STATE",
      type: "BOOLEAN_OR_STATE",
      subject: String(utteranceAct?.target || "CURRENT_OBJECT"),
      predicate: "CURRENT_OBJECT_OWNERSHIP_AND_ATTRIBUTE_STATUS",
      object: "ACTIVE_CHARACTER_IDENTITY",
      value: "UNKNOWN",
      source: "NO_CURRENT_TRUSTED_EVIDENCE",
      timeScope: "NOW",
      evidenceClass: "UNBOUND_CURRENT_OBJECT_STATE",
      assertionRights: {
        assertOwnershipTrue: "DENY",
        assertOwnershipFalse: "DENY",
        assertObjectAttribute: "DENY",
        knowledgeStatus: "ALLOW",
        useCanonicalSelfObjectReference: "ALLOW_WITH_CONTROLLED_EVIDENCE",
        identifyCurrentObjectAsSelf: "DENY_WITHOUT_MATCHING_FEATURE_EVIDENCE",
        alternateOwnerInvention: "DENY",
      },
    };
  }
  const clauses = splitSemanticClauses(value);
  const clause = clauses.find((item) =>
    ACTIVE_PERSONA_CURRENT_CLAUSE_RE.test(item)
    || ACTIVE_PERSONA_CURRENT_LOCATION_RE.test(item)
    || ACTIVE_PERSONA_CURRENT_ALT_LOCATION_RE.test(item)
    || CURRENT_SELF_ATTRIBUTION_RE.test(item)
    || activePersonaCurrentStateMention(item)
  ) || value;

  const activityQuery = r3CurrentPersonaActivityQuery(clause);
  const stateCue = String(clause.match(R6_CURRENT_STATE_CUE_RE)?.[0] || "").trim();
  const locationQuery = !activityQuery && !stateCue ? r5CurrentLocationQuery(clause) : null;
  const normalizedLocation = r6NormalizeCurrentLocation(locationQuery?.location || "");
  const activity = String(activityQuery?.activity || "").trim();
  const canonical = new Map([
    ["學校", "SELF_IS_AT_SCHOOL_NOW"],
    ["学校", "SELF_IS_AT_SCHOOL_NOW"],
    ["家", "SELF_IS_AT_HOME_NOW"],
    ["家裡", "SELF_IS_AT_HOME_NOW"],
    ["家里", "SELF_IS_AT_HOME_NOW"],
    ["公司", "SELF_IS_AT_WORK_NOW"],
    ["教室", "SELF_IS_IN_CLASSROOM_NOW"],
    ["宿舍", "SELF_IS_AT_DORM_NOW"],
  ]);
  const stateKind = activity ? "ACTIVITY" : stateCue ? "STATE" : normalizedLocation ? "LOCATION" : "UNRESOLVED_STATE";
  return {
    propositionId: "P_CURRENT_STATE",
    type: "BOOLEAN_OR_STATE",
    subject: "ACTIVE_CHARACTER_IDENTITY",
    predicate: activity
      ? "SELF_IS_PERFORMING_ACTIVITY_NOW"
      : stateCue
        ? "SELF_CURRENT_STATE"
        : canonical.get(normalizedLocation) || (normalizedLocation ? "SELF_IS_AT_LOCATION_NOW" : "SELF_CURRENT_STATE"),
    object: activity || stateCue || normalizedLocation || null,
    stateKind,
    ...(activityQuery?.locationContext ? { locationContext: activityQuery.locationContext } : {}),
    value: "UNKNOWN",
    source: "NO_CURRENT_TRUSTED_EVIDENCE",
    timeScope: "NOW",
    evidenceClass: "UNBOUND_CURRENT_STATE",
    assertionRights: {
      assertTrue: "DENY",
      assertFalse: "DENY",
      knowledgeStatus: "ALLOW",
      exactLocationSubstitution: "DENY",
      alternateStateInvention: "DENY",
    },
  };
}

function r3SelfCapabilityProposition(text) {
  const value = String(text || "");
  const activity = value.match(/(?:你|妳)?(?:會|会|能|可以)\s*(?:幫忙|帮忙)?\s*(裝|安装|安裝|修|修復|修复|設定|设置|配置|排查|處理|处理|寫|写|編寫|编写|算|計算|计算|整理|分析|查|搜尋|搜索|下載|下载|部署|連接|连接|重灌|重装|轉檔|转档|剪輯|剪辑|建立|生成)\s*([^，,。！？!?]{0,72})/u);
  const verb = String(activity?.[1] || "").trim();
  const object = String(activity?.[2] || "").trim();
  const windowsDriver = /Windows.{0,12}(?:驅動|驱动)/iu.test(`${verb} ${object}`);
  return {
    propositionId: "P_SELF_CAPABILITY",
    type: "CAPABILITY",
    subject: "ACTIVE_CHARACTER_IDENTITY",
    predicate: windowsDriver && /修|修復|修复|排查|處理|处理/u.test(verb)
      ? "SELF_CAN_REPAIR_WINDOWS_DRIVERS"
      : "SELF_CAPABILITY_FOR_REQUESTED_ACTIVITY",
    activity: [verb, object].filter(Boolean).join(" ").trim() || value,
    value: "UNKNOWN",
    source: "NO_CANONICAL_CHARACTER_CAPABILITY_BINDING",
    timeScope: "STABLE_OR_UNSPECIFIED",
    evidenceClass: "UNBOUND_CHARACTER_CAPABILITY",
    assertionRights: {
      assertCapable: "DENY",
      assertIncapable: "DENY",
      knowledgeStatus: "ALLOW",
      proceduralKnowledgeSubstitution: "DENY",
      skillLevelSubstitution: "DENY",
      experienceSubstitution: "DENY",
    },
  };
}

