        source: "CURRENT_USER_REPORT",
        sourceEntity: named ? String(parsed?.sourceEntity || "UNRESOLVED_REPORT_SOURCE") : "UNRESOLVED_HEARSAY_SOURCE",
        eventText: String(premise?.text || "").trim(),
