function r3InterpersonalRequestProposition(text, utteranceAct) {
  const roleBound = Boolean(utteranceAct?.requestedSpeaker || utteranceAct?.requestedAddressee || utteranceAct?.requestedUtterance);
  const userActionStance = utteranceAct?.subtype === "USER_ACTION_PERSONA_STANCE";
  const canonicalActionGrounding = userActionStance && utteranceAct?.canonicalGrounding !== false;
  return {
    propositionId: "P_INTERPERSONAL_REQUEST",
    type: "INTERPERSONAL_REQUEST",
    subject: "CURRENT_USER",
    predicate: userActionStance ? "USER_REQUESTS_PERSONA_STANCE_ON_INTENDED_ACTION" : "USER_REQUESTS_CHARACTER_RESPONSE_OR_ACTION",
    object: String(utteranceAct?.activity || text || "").trim(),
    value: "PENDING_CHARACTER_RESPONSE",
    source: "CURRENT_USER_REQUEST",
    timeScope: "THIS_TURN",
    evidenceClass: canonicalActionGrounding ? "USER_REQUEST_WITH_CANONICAL_GROUNDING" : "USER_REQUEST",
    ...(utteranceAct?.requestedSpeaker ? { requestedSpeaker: utteranceAct.requestedSpeaker } : {}),
    ...(utteranceAct?.requestedAddressee ? { requestedAddressee: utteranceAct.requestedAddressee } : {}),
    ...(utteranceAct?.requestedUtterance ? { requestedUtterance: utteranceAct.requestedUtterance } : {}),
    assertionRights: {
      accept: "ALLOW",
      decline: "ALLOW",
      counter: "ALLOW",
      react: "ALLOW",
      claimPhysicalActionOccurred: "DENY",
      claimCurrentActionAlreadyUnderway: "DENY",
      ...(canonicalActionGrounding
        ? { canonicalGrounding: "REQUIRED", canonicalMetadataAnswerOwnership: "DENY" }
        : {}),
      ...(String(utteranceAct?.requestMode || "").startsWith("speech_") || roleBound
        ? { requestPayloadFactPromotion: "DENY", roleInversion: "DENY" }
        : {}),
    },
  };
}

